fn parity_producer_inspects_selected_prepared_runtime_instead_of_controller_runtime() {
    if isolated("parity_producer_inspects_selected_prepared_runtime_instead_of_controller_runtime")
    {
        return;
    }
    process::operation(|| {
        let controller = Fixture::new();
        let selected = Fixture::new();
        let valid = include_str!("../runtime_slice/prepared_admission.cpp");
        let invalid = valid.replace("skippy_model * stage_model", "if (model->arch == LLM_ARCH_LLAMA) { return SKIPPY_STATUS_OK; } skippy_model * stage_model");
        assert_ne!(valid, invalid);
        let write_runtime = |fixture: &Fixture, source: &str| -> DynResult<()> {
            let native = fixture.root.join(".deps/llama.cpp");
            fs::create_dir_all(native.join("src/skippy"))?;
            fs::write(native.join("src/skippy/model_loading.cpp"), source)?;
            fs::write(native.join(".git/info/exclude"), ".mesh-llm-*\n")?;
            let head = commit(&native);
            fs::write(native.join(".mesh-llm-patched-sha"), format!("{head}\n"))?;
            Ok(())
        };
        write_runtime(&controller, valid)?;
        write_runtime(&selected, valid)?;
        let input = serde_json::from_value::<super::super::parity_inventory::Input>(json!({"context":{"controller_root":controller.root,"controller_revision":controller.authority.base,"selected_source":selected.authority.base,"run_id":"100","run_attempt":"1"},"root":selected.root,"base":selected.authority.base,"source_revision":selected.authority.base}))?;
        assert_eq!(super::super::parity_inventory::execute(&input)?["status"], "parity_inventory_admitted");
        write_runtime(&selected, &invalid)?;
        assert!(super::super::parity_inventory::execute(&input).is_err());
        write_runtime(&selected, valid)?;
        write_runtime(&controller, &invalid)?;
        assert_eq!(super::super::parity_inventory::execute(&input)?["status"], "parity_inventory_admitted");
        controller._temp.close()?;
        selected._temp.close()?;
        Ok(())
    }).unwrap();
}

fn serving_entry_selects_first_shard_before_smaller_later_shard_or_projector() {
    let file = |name: &str, size_bytes| PinnedFile {
        name: name.into(),
        url: String::new(),
        size_bytes,
        sha256: "a".repeat(64),
    };
    let mut files = vec![
        file("nested/Model-Q4_K_M-00002-of-00002.gguf", 1),
        file("nested/mmproj.gguf", 0),
        file("nested/Model-Q4_K_M-00001-of-00002.gguf", 100),
        file("single.gguf", 2),
    ];
    assert_eq!(
        serving_file(&files).unwrap().name,
        "nested/Model-Q4_K_M-00001-of-00002.gguf"
    );
    files.reverse();
    assert_eq!(
        serving_file(&files).unwrap().name,
        "nested/Model-Q4_K_M-00001-of-00002.gguf"
    );
    assert!(
        serving_file(&[file("model-00002-of-00002.gguf", 1), file("mmproj.gguf", 2)]).is_err()
    );
    assert_eq!(
        serving_file(&[file("single.gguf", 2)]).unwrap().name,
        "single.gguf"
    );
}

#[test]

fn parity_frontdoor_actual_cli_composes_full_source_roster_offline_defaults_and_retained_run() {
    let root = tempfile::tempdir().unwrap();
    let bytes = gguf();
    let authority = source_authority(root.path(), &bytes);
    for (repo, name, data) in [
        ("pinned", "model.gguf", bytes.clone()),
        ("discovered", "model-00002-of-00002.gguf", b"later".to_vec()),
        ("discovered", "model-00001-of-00002.gguf", bytes.clone()),
        ("corrupt", "broken.gguf", b"bad GGUF".to_vec()),
    ] {
        let dir = root.path().join(format!(
            "cache/models--fixture--{repo}/snapshots/{}",
            "a".repeat(40)
        ));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join(name), data).unwrap();
    }
    let mut request = json!({"authority":authority,"cache_root":root.path().join("cache"),"mode":"inventory","statuses":[],"families":[],"llama_models":[],"priorities":[],"limit":null,"missing_only":false,"local_only":false,"policy":{"skip_build":true,"prefix_token_count":8,"cache_hit_repeats":2,"borrow_resident_hits":true},"run":null,"admission_seconds":20});
    let (ok, stdout, stderr) = run_verb(root.path(), &request, "parity-local");
    assert!(ok, "{stderr}");
    let result: Value = serde_json::from_str(&stdout).unwrap();
    assert_eq!(result["admission"]["model_sources"], 1);
    assert_eq!(result["inventory"].as_array().unwrap().len(), 4);
    assert_eq!(result["inventory"][0]["status"], "local_verified");
    assert_eq!(result["inventory"][0]["classification"], "certified");
    assert!(
        result["inventory"][0]["local_path"]
            .as_str()
            .unwrap()
            .contains("models--fixture--pinned")
    );
    assert_eq!(result["inventory"][1]["status"], "local_verified");
    assert_eq!(
        result["inventory"][1]["identity_scope"],
        "observed_offline_cache_not_provider_pin"
    );
    assert_eq!(result["inventory"][2]["status"], "inspect_error");
    assert_eq!(result["inventory"][3]["status"], "missing");
    assert_eq!(result["prepared_plan"]["policy"]["ctx_size"], 77);
    assert_eq!(result["prepared_plan"]["policy"]["n_gpu_layers"], 9);
    request["missing_only"] = true.into();
    let (ok, stdout, stderr) = run_verb(root.path(), &request, "parity-local");
    assert!(ok, "{stderr}");
    assert_eq!(
        serde_json::from_str::<Value>(&stdout).unwrap()["inventory"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    request["missing_only"] = false.into();
    let setup = execution_input(root.path(), result["prepared_plan"].clone(), "successful");
    let mut settings = setup.as_object().unwrap().clone();
    settings.remove("plan");
    request["policy"]["ctx_size"] = 20.into();
    request["policy"]["n_gpu_layers"] = (-1).into();
    request["mode"] = "run".into();
    request["run"] = json!(settings);
    let (ok, _, stderr) = run_verb(root.path(), &request, "parity-local");
    assert!(ok, "{stderr}");
    let receipt: Value =
        serde_json::from_slice(&std::fs::read(root.path().join("run/run-receipt.json")).unwrap())
            .unwrap();
    assert_eq!(receipt["planned_candidates"], 2);
    assert_eq!(receipt["completed_receipts"], 2);
    for (index, kind) in [(0, "resident-kv"), (1, "kv-recurrent")] {
        let args: Value = serde_json::from_slice(
            &std::fs::read(
                root.path()
                    .join(format!("run/candidate-{index:04}/harness/arguments.json")),
            )
            .unwrap(),
        )
        .unwrap();
        let args: Vec<_> = args
            .as_array()
            .unwrap()
            .iter()
            .map(|s| s.as_str().unwrap())
            .collect();
        assert!(args.windows(2).any(|pair| pair == ["--ctx-size", "48"]));
        assert!(args.windows(2).any(|pair| pair == ["--n-gpu-layers", "-1"]));
        assert!(
            args.windows(2)
                .any(|pair| pair == ["--state-payload-kind", kind])
        );
    }
    assert_final_source_refusal(root.path(), &mut request);
    root.close().unwrap();
}
