fn parity_run_actual_cli_binds_harness_manifest_and_preserves_failed_partial_receipts() {
    for (prompt, stop) in [
        ("successful", false),
        ("sanitized-path", false),
        ("fail", false),
        ("wrong-identity", false),
        ("missing-manifest", false),
        ("fail", true),
    ] {
