fn serving_entry_selects_first_shard_before_smaller_later_shard_or_projector() {
    let file = |name: &str, size_bytes| PinnedFile {
        name: name.into(),
        url: String::new(),
        size_bytes,
        sha256: "a".repeat(64),
    };
    let mut files = vec![
        file("nested/Model-Q4_K_M-00002-of-00002.gguf", 1),
