                serde_json::from_str::<Value>(&stdout).unwrap()["status"],
                "completed"
            );
            assert_eq!(
                receipt["receipts"][0]["status"],
                "process_completed_manifest_bound"
            );
        } else {
            assert_eq!(receipt["status"], "failed");
            assert_eq!(receipt["receipts"][0]["status"], "failed");
        }
        root.close().unwrap();
    }
}
